// Gamer names (src/online/names.js): bad names are blocked even when disguised with numbers, spacing, repeated letters
// or look-alike letters; normal names (including ones that contain a bad word by accident) still work.
// The database runs the same rules (supabase/badwords.sql, generated by scripts/gen-badwords-sql.mjs).
import { checkName, online } from '../src/online/board.js';
let pass = 0, fail = 0;
const check = (ok, msg) => { if (ok) pass++; else { fail++; console.log('FAIL ' + msg); } };

export const ALLOWED = [
  'Noe', 'abc Pilgrim 7', 'Faith_Runner', 'x.y-z', 'Player1234567890', 'Pilgrim 2026', 'GodIsGood', 'Psalm23',
  'Bob', 'Bobby B', 'Classy Runner', 'Grass Hopper', 'Bass Drop', 'Compass Rose', 'Glass Cube', 'Mass Effect',
  'Document', 'Cucumber', 'Grape Juice', 'Scrapper', 'Peacock', 'Torpedo', 'Shell Shock', 'Hello World',
  'Hellooo', 'Scrap Yard', 'Analog Kid', 'Canal Street', 'Banal', 'Essex Lad', 'Sextant', 'Raccoon', 'Kung Fu Panda',
  'Pisces', 'Pisa Tower', 'Titan', 'Titus', 'Petition', 'Sussex', 'Matthew', 'Shiloh', 'Nazareth', 'Hit Man', 'Sky Walker',
  'Dashing Dove', 'Assisi', 'Grace 777', 'King David', 'Lion of Judah', 'Moses', 'Hope', 'Faith 3000',
];
export const BLOCKED = [
  // plain
  'fuck', 'Shit Head', 'bitch', 'Whore', 'Slut 99', 'Hitler', 'Nazi', 'Pussy Cat', 'dick', 'Penis', 'porn star',
  // numbers for letters
  'sh1t', 'b1tch', 'f4ggot', 'n1gg4', 'N1GGA', 'h1tl3r', 'p0rn', 'c0ck', 'a55', 'a55hole', 'b00b', 'p3n1s', 'd1ck',
  'r4pe', 'r4p3', '5lut', 'wh0r3', 'pu55y', 'cum', 'c u m', '7its',
  // spacing and dots
  'f u c k', 'f.u.c.k', 'f_u_c_k', 'F-U-C-K', 's h i t', 'b.i.t.c.h', 'n i g g a', 'a s s', 'p.0.r.n',
  // repeated letters
  'fuuuuck', 'shiiiit', 'biiitch', 'asssss', 'fuckkkk', 'phuuuk', 'niiiigga',
  // look-alikes
  'fvck', 'phuck', 'phuk', 'shlt', 'fuq', 'fcuk', 'fck you', 'biatch', 'kunt', 'sh1tty', 'shyt',
  // hidden in CamelCase or inside other words
  'BigAss', 'DumbAss', 'b1g4ss', 'JackAss', 'SmartAss 1', 'BadAss', 'MotherF', 'Fatass', 'xXFuckXx', 'IHateNiggas',
  'KillYourself', 'kys', 'Raped', 'rape', 'Anal', 'Sex', 'Sexy Girl', 'Tits', 'Horny', 'XXX Cube', 'kkk', 'Retard',
  'Douche', 'Bastard', 'Piss', 'Pissed Off', 'Damn It', 'Hell', 'wtf', 'STFU', 'Meth Head', 'Coon', 'Spic', 'Chink',
  'Kike', 'Dyke', 'Homo', 'Fag', 'Faggot', 'Tranny', 'Pedo', 'Pedophile', 'Molester', 'Hentai', 'Dildo', 'Jizz',
];
if (process.argv[1] && process.argv[1].endsWith('board.test.mjs')) {
  for (const n of ALLOWED) { const r = checkName(n); check(r.ok, `"${n}" should be allowed (${r.error})`); }
  for (const n of BLOCKED) { const r = checkName(n); check(!r.ok, `"${n}" should be blocked`); }
  for (const n of ['', 'ab', '12345678901234567', 'hi<b>', 'emoji😀x', 'a/b/c', '12345', 'shit@']) check(!checkName(n).ok, `"${n}" is refused (format)`);
  check(checkName('  spaced   out  ').name === 'spaced out', 'extra spaces are tidied');
  check(typeof online() === 'boolean', 'online() reports whether the leaderboard is connected');
  console.log(`${pass} passed, ${fail} failed`);
  process.exitCode = fail ? 1 : 0;
}
